"""Join two independently measured backbones for the same phonetic site."""
from __future__ import annotations

import numpy as np

from hindi_detector.dual_paired_vowels import FEATURE_NAMES
from hindi_detector.paired_local_inference import analyze_pair as single_pair


def analyze_pair(query,reference,secondary_query,secondary_reference,word_lookup,ipa,vocabulary,secondary_vocabulary):
    words,sites,features=single_pair(query,reference,word_lookup,ipa,vocabulary)
    other_words,other_sites,other_features=single_pair(secondary_query,secondary_reference,word_lookup,ipa,secondary_vocabulary)
    if [w['word'] for w in words]!=[w['word'] for w in other_words]:raise ValueError('Two probes lost canonical word identity')
    def key(site):return site['word_ordinal'],site['site']['kind'],site['site']['index'],tuple(site['native_phones'])
    lookup={key(s):s for s in other_sites}
    if len(lookup)!=len(other_sites):raise ValueError('Duplicate second-probe phonetic identity')
    retained=[];vectors=[]
    for site in sites:
        other=lookup.get(key(site))
        if other is None:
            words[site['word_ordinal']]['unavailable_reasons'].append('Second probe cannot support the same reference-selected Native variant/site')
            continue
        primary=site['features'];secondary=other['features'];f=np.r_[primary,secondary].astype(np.float32)
        site.update(primary_features=primary,secondary_features=secondary,features=f.tolist(),secondary=other)
        retained.append(site);vectors.append(f)
    for ordinal,word in enumerate(words):word['sites']=[s for s in retained if s['word_ordinal']==ordinal]
    return words,retained,np.stack(vectors) if vectors else np.empty((0,len(FEATURE_NAMES)),np.float32)

"""Pinned local two-phone-model runtime; no hidden downloads or substitutions."""
from __future__ import annotations

import json

import numpy as np
import torch
from transformers import AutoFeatureExtractor,AutoModelForCTC

from hindi_detector.corrected_synthesis import sha


class PhonePair:
    def __init__(self,root,state,device='mps',primary_engine=None):
        if device not in {'cpu','mps'} or device=='mps' and not torch.backends.mps.is_available():raise ValueError('Unavailable phone device')
        self.device=device;self.models=[];self.vocabularies=[]
        inventories=[state['phone_inventory'],state['secondary_phone_inventory']]
        for index,directory in enumerate([root/'models/phoneme_probe',root/'models/phoneme_probe_lv60_v20']):
            actual=json.loads((directory/'inventory.json').read_text())
            if actual!=inventories[index]:raise ValueError('Requested checkpoint inventory differs')
            for member in actual['files']:
                path=directory/member['path']
                if path.stat().st_size!=member['bytes'] or sha(path)!=member['sha256']:raise ValueError('Phone checkpoint bytes changed')
            vocabulary=json.loads((directory/'vocab.json').read_text());self.vocabularies.append(vocabulary)
            if {k:vocabulary[k] for k in ('<pad>','<s>','</s>','<unk>')}!={'<pad>':0,'<s>':1,'</s>':2,'<unk>':3}:raise ValueError('Unexpected phone special IDs')
            if index==0 and primary_engine is not None:
                if primary_engine.phone_inventory!=actual or primary_engine.device!=device:raise ValueError('Shared primary runtime differs')
                extractor,model=primary_engine.extractor,primary_engine.phone
            else:
                extractor=AutoFeatureExtractor.from_pretrained(directory,local_files_only=True)
                model=AutoModelForCTC.from_pretrained(directory,local_files_only=True).eval().to(device)
            if extractor.sampling_rate!=16000 or model.config.pad_token_id!=0:raise ValueError('Unexpected phone input/blank')
            self.models.append((extractor,model))
        torch.set_num_threads(2)

    def encode_one(self,samples,index):
        samples=np.asarray(samples,np.float32)
        if samples.ndim!=1 or not 3200<=len(samples)<=30*16000 or not np.isfinite(samples).all():raise ValueError('Need finite16k mono speech between0.2 and30sec')
        if self.device=='mps' and len(samples)>20*16000:raise ValueError('Long utterance requires whole-group CPU execution')
        extractor,model=self.models[index]
        with torch.inference_mode():
            output=model(**{k:v.to(self.device) for k,v in extractor(samples,sampling_rate=16000,return_tensors='pt').items()})
            lp=output.logits[0].log_softmax(-1).cpu().numpy()
        if lp.ndim!=2 or lp.shape[1]!=len(self.vocabularies[index]) or not np.isfinite(lp).all():raise ValueError('Invalid measured phone posterior')
        return lp

    def encode(self,samples):return [self.encode_one(samples,index) for index in (0,1)]

"""Descriptive human-variation context; never an input to model decisions."""
from __future__ import annotations

import json
from pathlib import Path

from hindi_detector.corrected_synthesis import sha


def load_bank(directory: Path, model: Path) -> dict | None:
    path = directory / 'native_observations.json'
    if not path.exists():
        return None
    bank = json.loads(path.read_text())
    if bank['schema'] != 'observed_real_variation_v1' or bank['model_sha256'] != sha(model):
        raise ValueError('Observed-variation bank model identity differs')
    return bank


def matching_observations(bank: dict | None, word: str, site: dict, native_phones: list, *, exclude_case: str | None = None) -> dict:
    if bank is None:
        return {'status': 'bank_unavailable', 'used_for_prediction': False}
    entries = [entry for entry in bank['entries'] if entry['word'] == word
               and entry['site']['kind'] == site['kind'] and entry['site']['index'] == site['index']
               and entry['native_phones'] == native_phones
               and entry['site'].get('alternative') == site.get('alternative')]
    cases = [case for entry in entries for case in entry['recordings'] if case['id'] != exclude_case]
    return {'status': 'observed_in_other_real_recordings' if cases else 'not_observed_in_limited_bank',
            'cases': cases, 'source_groups': len({case['voice'] for case in cases}),
            'human_error_label': None, 'used_for_prediction': False,
            'meaning': 'Observed probe-supported alternative in recorded speech, potentially including contextual or regional variation; acceptability and Hindi influence remain unconfirmed.'}
